import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Easing,
} from '../remotionShim';
// Font Loader Logic
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(`link[href*="${font.replace(/\s+/g, "+")}"]`)
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;700;900`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};



export type FunnelOptimizerProps = Record<string, any>;

const ListItem: React.FC<{
  index: number;
  badge: string;
  text: string;
  boxSizeRatio: number;
  expandedWidthRatio: number;
  borderColor: string;
  contentBackgroundColor: string;
  badgeColor: string;
  badgeTextColor: string;
  contentTextColor: string;
}> = ({
  index,
  badge,
  text,
  boxSizeRatio,
  expandedWidthRatio,
  borderColor,
  contentBackgroundColor,
  badgeColor,
  badgeTextColor,
  contentTextColor,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Dimensions
  const boxSize = height * boxSizeRatio;
  const maxTotalWidth = width * expandedWidthRatio;
  const borderThickness = boxSize * 0.05;
  const fontSizeBadge = boxSize * 0.5;
  const fontSizeMain = boxSize * 0.25;

  // Animation Timing
  const startDelay = 10 + index * 25; // Staggered start per item
  const expandDelay = startDelay + 30;

  // 1. Initial Pop In (Scale)
  const scale = spring({
    frame: frame - startDelay,
    fps,
    config: {
      damping: 12,
      stiffness: 100,
    },
  });

  // 2. Expansion (Width)
  const expansionProgress = spring({
    frame: frame - expandDelay,
    fps,
    config: {
      damping: 20,
      stiffness: 60,
      mass: 1,
    },
  });

  const currentTotalWidth = interpolate(
    expansionProgress,
    [0, 1],
    [boxSize, maxTotalWidth],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // 3. Text Reveal (Opacity & Slide)
  const textOpacity = interpolate(
    frame - expandDelay - 5,
    [0, 20],
    [0, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.out(Easing.ease),
    }
  );

  const textTranslateX = interpolate(
    expansionProgress,
    [0, 1],
    [-50, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  return (
    <div
      style={{
        height: boxSize,
        width: currentTotalWidth,
        border: `${borderThickness}px solid ${borderColor}`,
        display: "flex",
        flexDirection: "row",
        overflow: "hidden",
        transform: `scale(${scale})`,
        backgroundColor: contentBackgroundColor,
        boxShadow: `0px ${borderThickness}px 0px rgba(0,0,0,0.1)`,
      }}
    >
      {/* Badge Area */}
      <div
        style={{
          minWidth: boxSize - borderThickness * 2,
          flexBasis: boxSize - borderThickness * 2,
          backgroundColor: badgeColor,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          zIndex: 2,
          position: "relative",
        }}
      >
        <h1
          style={{
            color: badgeTextColor,
            fontSize: fontSizeBadge,
            fontWeight: 900,
            margin: 0,
            lineHeight: 1,
          }}
        >
          {badge}
        </h1>
      </div>

      {/* Content Area */}
      <div
        style={{
          flex: 1,
          display: "flex",
          justifyContent: "flex-start",
          alignItems: "center",
          paddingLeft: boxSize * 0.2,
          opacity: textOpacity,
          transform: `translateX(${textTranslateX}px)`,
          whiteSpace: "nowrap",
          backgroundColor: contentBackgroundColor,
        }}
      >
        <span
          style={{
            color: contentTextColor,
            fontSize: fontSizeMain,
            fontWeight: 800,
            textTransform: "uppercase",
            letterSpacing: "0.02em",
          }}
        >
          {text}
        </span>
      </div>
    </div>
  );
};

const FunnelOptimizer: React.FC<FunnelOptimizerProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = true,
  badgeColor = "#6225E6",
  badgeTextColor = "#ffffff",
  contentBackgroundColor = "#ffffff",
  contentTextColor = "#000000",
  borderColor = "#000000",
  badgeText = "#1",
  mainText = "OPTIMIZE HIS FUNNEL",
  badgeText2 = "#2",
  mainText2 = "SCALE THE WINNERS",
  badgeText3 = "#3",
  mainText3 = "AUTOMATE DELIVERY",
  boxSizeRatio = 0.15,
  expandedWidthRatio = 0.6,
  durationInSeconds = 5,
}) => {
  useFontLoader(["Inter"]);
  const { height } = useVideoConfig();

  // Colors
  const bg = transparentBackground ? "transparent" : backgroundColor;

  const points = [
    { badge: badgeText, text: mainText },
    { badge: badgeText2, text: mainText2 },
    { badge: badgeText3, text: mainText3 },
  ];

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bg,
        justifyContent: "center",
        alignItems: "center",
        fontFamily: "Inter, sans-serif",
        flexDirection: "column",
        gap: height * 0.03, // Dynamic gap based on height
      }}
    >
      {points.map((point, index) => (
        <ListItem
          key={index}
          index={index}
          badge={point.badge}
          text={point.text}
          boxSizeRatio={boxSizeRatio}
          expandedWidthRatio={expandedWidthRatio}
          borderColor={borderColor}
          contentBackgroundColor={contentBackgroundColor}
          badgeColor={badgeColor}
          badgeTextColor={badgeTextColor}
          contentTextColor={contentTextColor}
        />
      ))}
    </AbsoluteFill>
  );
};

export default FunnelOptimizer;